import AppKit

/// "Offer what I copy to my phone" (off by default). While it runs, it reads only
/// `NSPasteboard.changeCount` every 1.5 s; the contents are read once per change, after the
/// clipboard has stayed the same for one more tick (debounce). It runs only while the
/// setting is on and a paired phone marked "mine" is around; the model starts and stops it.
///
/// Only plain/rich text up to 64 KiB is offered. Anything marked concealed, transient or
/// auto-generated (password managers, clipboard tools: see nspasteboard.org) is skipped, as
/// are files, images and other non-text content.
final class ClipboardWatcher {
    /// Called on the main thread with text to send.
    var onText: ((String) -> Void)?

    static let interval: TimeInterval = 1.5
    static let maxBytes = 65_536

    private var timer: Timer?
    private var lastSeen = 0
    private var pending: Int?
    private var ignored: Set<Int> = []
    private var lastOffered: String?

    var isRunning: Bool { timer != nil }

    func start() {
        guard timer == nil else { return }
        // What is on the clipboard already is not sent: only what is copied from now on.
        lastSeen = NSPasteboard.general.changeCount
        pending = nil
        let timer = Timer(timeInterval: Self.interval, repeats: true) { [weak self] _ in self?.tick() }
        timer.tolerance = 0.3
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    func stop() {
        timer?.invalidate()
        timer = nil
        pending = nil
    }

    /// The app itself just wrote the clipboard (text or a photo from the phone): never echo it back.
    func ignore(changeCount: Int) {
        ignored.insert(changeCount)
        if ignored.count > 16 { ignored.remove(ignored.min() ?? changeCount) }
    }

    private func tick() {
        let pasteboard = NSPasteboard.general
        let count = pasteboard.changeCount
        if count != lastSeen {
            lastSeen = count
            pending = count
            return
        }
        guard let ready = pending, ready == count else { return }
        pending = nil
        guard !ignored.contains(ready), let text = Self.offerableText(pasteboard), text != lastOffered else { return }
        lastOffered = text
        onText?(text)
    }

    /// Markers apps put on clipboard contents that must not be synced or recorded.
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
        "com.agilebits.onepassword",
    ]

    static func offerableText(_ pasteboard: NSPasteboard) -> String? {
        let types = pasteboard.types ?? []
        if types.contains(where: { skippedTypes.contains($0.rawValue) }) { return nil }
        // Text only: a copy that carries files or images is not offered.
        guard types.contains(.string), !types.contains(.fileURL), !types.contains(.tiff),
              !types.contains(.png), !types.contains(.pdf) else { return nil }
        guard let text = pasteboard.string(forType: .string),
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              text.utf8.count <= maxBytes else { return nil }
        return text
    }
}
